validator:
function validate(input) {
  const [{ Sales = [], Product = [] }] = input;
  const products = new Set(), sales = new Set();
  for (const [id, price] of Product) {
    if (id === null) return 'Every product needs a product_id.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    products.add(id);
    if (price === null || price <= 0) return `Product ${id} needs a positive price.`;
  }
  for (const [id, product, user, quantity] of Sales) {
    if (id === null) return 'Every sale needs a sale_id.';
    if (sales.has(id)) return `sale_id ${id} appears twice in Sales.`;
    sales.add(id);
    if (!products.has(product)) return `Sale ${id} names product ${product}, which is not in Product.`;
    if (user === null) return `Sale ${id} needs a user_id.`;
    if (quantity === null || quantity <= 0) return `Sale ${id} needs a positive quantity.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const Product = [], Sales = [];
  if (size === 'small') {
    // Few products with round prices and few users, so totals tie often.
    const prices = [5, 10, 15, 25, 30];
    const productCount = 1 + Math.floor(rand() * 4);
    for (let id = 1; id <= productCount; id++) Product.push([id, prices[Math.floor(rand() * prices.length)]]);
    const count = Math.floor(rand() * 9);
    for (let id = 1; id <= count; id++) Sales.push([id, 1 + Math.floor(rand() * productCount), 104 - Math.floor(rand() * 5), 1 + Math.floor(rand() * 4)]);
  } else {
    for (let id = 1; id <= 200; id++) Product.push([id, 1 + Math.floor(rand() * 100)]);
    for (let id = 1; id <= 2000; id++) Sales.push([id, 1 + Math.floor(rand() * 200), 1 + Math.floor(rand() * 300), 1 + Math.floor(rand() * 20)]);
  }
  return [{ Sales, Product }];
}
